using System.Linq;using System.Text;using UnityEditor;using UnityEngine;
namespace XuanwuTools { public static class AssetAuditor {
 [MenuItem(Common.Menu+"05 Audit selected models")] public static void Audit()=>Common.Run(()=>{var sb=new StringBuilder();foreach(var o in Selection.gameObjects){var meshes=o.GetComponentsInChildren<MeshFilter>(true).Select(x=>x.sharedMesh).Where(x=>x).Distinct().ToArray();sb.AppendLine(o.name+" mesh count="+meshes.Length+" LODGroups="+o.GetComponentsInChildren<LODGroup>(true).Length+" colliders="+o.GetComponentsInChildren<Collider>(true).Length);foreach(var m in meshes){ulong triangles=0;for(int i=0;i<m.subMeshCount;i++)if(m.GetTopology(i)==MeshTopology.Triangles)triangles+=m.GetIndexCount(i)/3;sb.AppendLine($" {m.name} tris={triangles} bounds={m.bounds.size} readable={m.isReadable}");}foreach(var mat in o.GetComponentsInChildren<Renderer>(true).SelectMany(x=>x.sharedMaterials).Where(x=>x).Distinct()){sb.AppendLine(" mat="+mat.name+" shader="+mat.shader.name);foreach(var n in mat.GetTexturePropertyNames()){var tex=mat.GetTexture(n);if(tex)sb.AppendLine($"  {n} {tex.name} {tex.width}x{tex.height}");}}}Common.Report("assets",sb.ToString());});}}
